import axios from 'axios';
import { generateSignature } from '../signer/signer';
export async function getUserVideos(username, options = {}) {
    try {
        const url = `https://www.tiktok.com/@${username}`;
        const sig = await generateSignature(url);
        const res = await axios.get(url, {
            headers: {
                'User-Agent': 'Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/91.0.4472.124 Safari/537.36',
                'Referer': 'https://www.tiktok.com/',
                'x-tt-params': sig,
            },
        });
        const match = res.data.match(/<script id="__UNIVERSAL_DATA_FOR_REHYDRATION__" type="application\/json">(.+?)<\/script>/);
        if (!match)
            throw new Error('User data not found');
        const json = JSON.parse(match[1]);
        const items = json.props?.pageProps?.items || [];
        const filter = options.filter?.map(f => f.toLowerCase()) || [];
        const limit = options.limit || Infinity;
        const videos = items
            .map((item) => {
            const tags = (item.text?.match(/#(\w+)/g) || []).map((t) => t.toLowerCase());
            const matchFilter = filter.length === 0 || filter.some(f => item.text?.toLowerCase().includes(f) || tags.includes(`#${f}`));
            if (!matchFilter)
                return null;
            return {
                id: item.id,
                description: item.text || '',
                playCount: item.stats?.playCount || 0,
                likeCount: item.stats?.diggCount || 0,
                commentCount: item.stats?.commentCount || 0,
                shareCount: item.stats?.shareCount || 0,
                hashtags: tags,
                audio: {
                    id: item.music?.id || '',
                    title: item.music?.title || '',
                    videoCount: item.music?.stats?.videoCount || 0,
                },
            };
        })
            .filter(Boolean)
            .slice(0, limit);
        return videos;
    }
    catch (error) {
        throw new Error(`Failed to fetch user videos: ${error.message}`);
    }
}
export async function getUserProfile(username) {
    try {
        const url = `https://www.tiktok.com/@${username}`;
        const sig = await generateSignature(url);
        const res = await axios.get(url, {
            headers: {
                'User-Agent': 'Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/91.0.4472.124 Safari/537.36',
                'Referer': 'https://www.tiktok.com/',
                'x-tt-params': sig,
            },
        });
        const match = res.data.match(/<script id="__UNIVERSAL_DATA_FOR_REHYDRATION__" type="application\/json">(.+?)<\/script>/);
        if (!match)
            throw new Error('Profile data not found');
        const json = JSON.parse(match[1]);
        const userProfile = json.props?.pageProps?.userInfo;
        if (!userProfile)
            throw new Error('User profile not found');
        return {
            username: userProfile.nickname || username,
            followersCount: userProfile.followerCount || 0,
            followingCount: userProfile.followingCount || 0,
            bio: userProfile.signature || '',
            profilePicture: userProfile.avatarThumb || '',
        };
    }
    catch (error) {
        throw new Error(`Failed to fetch user profile: ${error.message}`);
    }
}
